negativeExample:
import java.util.ArrayList;
import java.util.List;
import org.eclipse.jface.text.rules.IRule;
import org.eclipse.jface.text.rules.IToken;
import org.eclipse.jface.text.rules.SingleLineRule;

public class NegativeTestClass {
    public void setupRules(List<IRule> list, IToken token) {
        // These should not be changed as their start patterns are not in the 'matchesAny' list
        list.add(new SingleLineRule("/*", "*/", token));
        list.add(new SingleLineRule("<!--", "-->", token));
        list.add(new SingleLineRule("@deprecated", "}", token));
    }
}
